void canHandler_init()
{
    // Configuration mode should be active, but request to be sure
    C1CONTbits.REQOP = 0b100;
    
    // Do not store transmitted bits
    C1CONUbits.STEF = 0;

    // CAN1 FIFO Memory base
    C1FIFOBA = 0x3800;
        
    // Bit Rate configuration
    //C1NBTCFGTbits.BRP = 3; // BRP = 4
    C1NBTCFGTbits.BRP = 0;
    //C1NBTCFGUbits.TSEG1 = 11; // TSEG1 = 12
    C1NBTCFGUbits.TSEG1 = 0x26;
    //C1NBTCFGHbits.TSEG2 = 2; // TSEG2 = 3
    C1NBTCFGHbits.TSEG2 = 0x17; 
    C1NBTCFGLbits.SJW = 0x17; //2; // SJW = TSEG2
        
    // Configure CAN1 FIFO settings
    // TFNRFNIE enabled;
    C1FIFOCON1Lbits.TFNRFNIE = 1;
    // TXAT Disables retransmission attempts; 
    C1FIFOCON1Ubits.TXAT = 0;
    // FSIZE 6; 
    C1FIFOCON1Tbits.FSIZE = 5;

    // Message stored in FIFO1
    C1FLTCON0Lbits.F0BP =  1;
    // No need to configure filter as we use mask to catch all
    C1FLTOBJ0Lbits.SID = 0x1;
    C1MASK0L = 0x0;
    C1MASK0H = 0x0;
    C1MASK0U = 0x0;
    C1MASK0T = 0x0;
    // Enable the filter 0
    C1FLTCON0Lbits.FLTEN0 = 1;

    // Recieve interupt enable
	C1INTUbits.RXIE = 1;

    // Enable interrupts globally
    PIR4bits.CANRXIF = 0;
    PIE4bits.CANRXIE = 1;
    
    // Transmit configuration
    // FSIZE 6, 0-index; 
    C1TXQCONTbits.FSIZE = 5;
    
    // Enable the CAN1 module
    C1CONHbits.ON = 1;
    
    // Enabled CAN1 Transmit Queue bit
    C1CONUbits.TXQEN = 1;
    
    // Place CAN1 module in Normal Operation mode
    C1CONTbits.REQOP = 6;
    
    // Wait for Normal Operation mode
    while(C1CONUbits.OPMOD != 6);

    // Initialize all message handlers
    for(int i = 0; i < sizeof(canMessageHandler_messages) / sizeof(canMessageHandler_messages[0]); i++)
    {
        canMessageHandler_messages[i].init();
    }
}

